 "content": "def transform(grid):
    """Mark disagreements between the two repeated horizontal bands."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    active_rows = [r for r in range(h) if any(v != bg for v in grid[r])]
    if len(active_rows) % 2:
        return out
    # Two similarly sized bands separated by blank rows.
    # Rows are paired in order; mark missing/extra foreground cells in the
    # first band where its counterpart has foreground, unless the first band
    # is the shorter visible rendering, in which case restore there.
    runs = []
    for r in active_rows:
        if not runs or r != runs[-1][-1] + 1:
            runs.append([r])
        else:
            runs[-1].append(r)
    if len(runs) == 2 and len(runs[0]) == len(runs[1]):
        first, second = runs
        # Determine canonical row template by foreground coverage; differences
        # are marked in the row that is the incomplete copy.
        for x, y in zip(first, second):
            a, b = grid[x], grid[y]
            for c in range(w):
                if a[c] != b[c]:
                    # Preserve the foreground-bearing side as the marked side
